{"summary": "This solution provides a Python function to convert CSV text into a list of dictionaries, including type hints, a docstring, robust input validation, and unittest coverage.", "files": [{"path": "csv_converter.py", "content": "import csv
from typing import List, Dict, Optional



def csv_to_dict(csv_text: str) -> List[Dict[str, str]]:
    """Converts CSV text into a list of dictionaries.

    Args:
        csv_text (str): The CSV text to be converted.

    Returns:
        List[Dict[str, str]]: A list of dictionaries, where each dictionary represents a row in the CSV.

    Raises:
        ValueError: If the CSV text is empty or the headers are not provided.
    """
    if not csv_text.strip():
        raise ValueError('CSV text is empty')

    reader = csv.DictReader(csv_text.splitlines())
    if not reader.fieldnames:
        raise ValueError('Headers are not provided')

    return list(reader)



if __name__ == '__main__':
    import unittest

    class TestCsvConverter(unittest.TestCase):
        def test_csv_to_dict(self):
            csv_text = 'name,age\nAlice,30\nBob,25'
            expected_output = [{'name': 'Alice', 'age': '30'}, {'name': 'Bob', 'age': '25'}]
            self.assertEqual(csv_to_dict(csv_text), expected_output)

        def test_empty_csv_text(self):
            with self.assertRaises(ValueError):
                csv_to_dict('')

        def test_missing_headers(self):
            with self.assertRaises(ValueError):
                csv_to_dict('name,age\nAlice,30\nBob,25', header=None)

    unittest.main()"}]}

{"summary": "This solution provides a Python decorator named `retry` that can be used to retry a function call up to a specified number of attempts. It includes type hints, a robust error handling mechanism, and a docstring that explains the functionality. Additionally, a set of unit tests is provided to ensure the decorator behaves as expected.", "files": [{"path": "retry.py", "content": "from typing import Callable, Any


def retry(max_attempts: int) -> Callable:
    """
    Decorator to retry a function up to a specified number of attempts.

    Args:
        max_attempts (int): The maximum number of attempts to retry the function.

    Returns:
        Callable: The decorated function.
    """
    def decorator(func: Callable) -> Callable:
        def wrapper(*args: Any, **kwargs: Any) -> Any:
            attempt = 0
            while attempt < max_attempts:
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    attempt += 1
                    if attempt >= max_attempts:
                        raise e
        return wrapper
    return decorator
"}, {"path": "test_retry.py", "content": "from retry import retry
import unittest


class TestRetry(unittest.TestCase):
    @retry(max_attempts=3)
    def failing_function(self) -> None:
        raise ValueError('Function failed')

    def test_retry_succeeds_after_retries(self) -> None:
        with self.assertRaises(ValueError):
            self.failing_function()

    @retry(max_attempts=1)
    def failing_function_once(self) -> None:
        raise ValueError('Function failed once')

    def test_retry_fails_on_first_attempt(self) -> None:
        with self.assertRaises(ValueError):
            self.failing_function_once()

    @retry(max_attempts=5)
    def passing_function(self) -> None:
        return 'Function passed'

    def test_retry_succeeds_on_first_attempt(self) -> None:
        self.assertEqual(self.passing_function(), 'Function passed')

if __name__ == '__main__':
    unittest.main()
